<div class="d-flex justify-content-between align-items-center mb-2 step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var step = i + 1;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isFuture = step > CurrentStep && !isCompleted;

        <div class="text-center flex-fill position-relative step-item">
            @if (i > 0)
            {
                <div class="step-connector @(CompletedSteps.Contains(step) || (step == CurrentStep && CompletedSteps.Contains(step - 1)) ? "completed" : "")"></div>
            }
            <button class="btn rounded-circle step-circle @(isActive ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary") @(isFuture ? "opacity-50" : "")"
                    disabled="@(isFuture)"
                    @onclick="() => OnStepClicked.InvokeAsync(step)"
                    style="width:40px;height:40px;padding:0;">
                @if (isCompleted && !isActive)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </button>
            <div class="small mt-1 @(isFuture ? "text-muted" : "") @(isActive ? "fw-bold" : "")">
                @_stepNames[i]
            </div>
        </div>
    }
</div>

