@namespace sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages

<h4>Step 1: Personal Information</h4>
<hr />

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control" value="@FullName"
           @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control" value="@Email"
           @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control" value="@Phone"
           @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control" rows="2" value="@Address"
              @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="OnNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next →</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public bool IsValidating { get; set; }
}

@namespace sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages
@using static sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages.Apply

<h4>Step 2: Work History</h4>
<hr />

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

@for (int i = 0; i < WorkEntries.Count; i++)
{
    var index = i;
    var entry = WorkEntries[index];

    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <span>Position @(index + 1)</span>
            @if (WorkEntries.Count > 1)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
            }
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@entry.Company"
                           @oninput="e => entry.Company = e.Value?.ToString() ?? """/>
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@entry.Title"
                           @oninput="e => entry.Title = e.Value?.ToString() ?? """/>
                </div>
            </div>
            <div class="row mb-3">
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@FormatDate(entry.StartDate)"
                           @onchange="e => entry.StartDate = ParseDate(e.Value?.ToString())"/>
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@FormatDate(entry.EndDate)"
                           disabled="@entry.IsCurrent"
                           @onchange="e => entry.EndDate = ParseNullableDate(e.Value?.ToString())"/>
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" checked="@entry.IsCurrent"
                               @onchange="e => { entry.IsCurrent = (bool)(e.Value ?? false); if(entry.IsCurrent) entry.EndDate = null; }" />
                        <label class="form-check-label">Currently working here</label>
                    </div>
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@entry.Description"
                          @oninput="e => entry.Description = e.Value?.ToString() ?? """></textarea>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">+ Add Another Position</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? ValidationError { get; set; }

    private void AddEntry() => WorkEntries.Add(new WorkEntryModel());
    private void RemoveEntry(int index) => WorkEntries.RemoveAt(index);

    private string FormatDate(DateTime date) =>
        date == default ? "" : date.ToString("yyyy-MM-dd");

    private string FormatDate(DateTime? date) =>
        date.HasValue ? date.Value.ToString("yyyy-MM-dd") : "";

    private DateTime ParseDate(string? value) =>
        DateTime.TryParse(value, out var d) ? d : default;

    private DateTime? ParseNullableDate(string? value) =>
        DateTime.TryParse(value, out var d) ? d : null;
}

@namespace sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages
@using static sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages.Apply

<h4>Step 3: References</h4>
<hr />

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var reference = References[index];

    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <span>Reference @(index + 1)</span>
            @if (References.Count > 2)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
            }
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@reference.Name"
                           @oninput="e => reference.Name = e.Value?.ToString() ?? """/>
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" value="@reference.Relationship"
                           @oninput="e => reference.Relationship = e.Value?.ToString() ?? """/>
                </div>
            </div>
            <div class="row mb-3">
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" value="@reference.Email"
                           @oninput="e => reference.Email = e.Value?.ToString() ?? """/>
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone</label>
                    <input type="tel" class="form-control" value="@reference.Phone"
                           @oninput="e => reference.Phone = e.Value?.ToString() ?? """/>
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">+ Add Reference</button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? ValidationError { get; set; }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => References.RemoveAt(index);
}

@namespace sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages

<h4>Step 4: Cover Letter</h4>
<hr />

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<div class="mb-3">
    <label class="form-label">Cover Letter <span class="text-danger">*</span></label>
    <textarea class="form-control" rows="12" maxlength="2000" value="@CoverLetter"
              @oninput="e => CoverLetterChanged.InvokeAsync(e.Value?.ToString() ?? "")"></textarea>
    <div class="form-text text-end">
        @(CoverLetter?.Length ?? 0) / 2000 characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? ValidationError { get; set; }
}

@namespace sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages
@using static sv_3f15f9f093954e7ea63067ecc6f200ea.Components.Pages.Apply

<h4>Step 5: Review & Submit</h4>
<hr />

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between">
        <strong>Personal Information</strong>
        <a href="#" @onclick:preventDefault @onclick="() => OnEditStep.InvokeAsync(1)">Edit</a>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@Address</dd>
        </dl>
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between">
        <strong>Work History</strong>
        <a href="#" @onclick:preventDefault @onclick="() => OnEditStep.InvokeAsync(2)">Edit</a>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3 pb-3 border-bottom">
                <h6>@entry.Title at @entry.Company</h6>
                <p class="text-muted mb-1">
                    @entry.StartDate.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </p>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0">@entry.Description</p>
                }
            </div>
        }
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between">
        <strong>References</strong>
        <a href="#" @onclick:preventDefault @onclick="() => OnEditStep.InvokeAsync(3)">Edit</a>
    </div>
    <div class="card-body">
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong>
                @if (!string.IsNullOrWhiteSpace(r.Relationship))
                {
                    <span class="text-muted">(@r.Relationship)</span>
                }
                <br />
                <small>@r.Email @(string.IsNullOrWhiteSpace(r.Phone) ? "" : $"· {r.Phone}")</small>
            </div>
        }
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between">
        <strong>Cover Letter</strong>
        <a href="#" @onclick:preventDefault @onclick="() => OnEditStep.InvokeAsync(4)">Edit</a>
    </div>
    <div class="card-body">
        <p style="white-space:pre-wrap;">@CoverLetter</p>
    </div>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
            <span>Submitting…</span>
        }
        else
        {
            <span>Submit Application</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
}

